    /// The scope stamped onto the ops of one agent edit — `performGroupedEdit`
    /// in the frozen file calls this, and it is the MCP mirror of
    /// `ProjectDocument.addressed(_:)`.
    ///
    /// **Two rules, and the difference between them is deliberate.** An
    /// EXPLICIT `scope` is stamped on every op, the seven document-level ones
    /// included, so an agent that asks for `add_media {scope: 4}` gets the
    /// core's own refusal by name rather than a silent redirection — it asked
    /// a question and the answer is no (`ReelOp.documentLevelNames` argues
    /// the other half of this). An INHERITED one skips them, exactly as
    /// `addressed` does, because a Finder drop inside a nest is an
    /// `add_media` on the document's one media list plus an `add_clip` in the
    /// nest, and an agent's `import_media` inside a nest is the same act.
    ///
    /// **Two of those seven may not be sent that way at all**, and
    /// `checkDocumentLevelTicks` below is the refusal: `add_marker` and a
    /// `set_marker` carrying a `time` would reach the timeline's `markers[]`
    /// at a tick the caller measured from the NEST's zero. Read the two
    /// together — this method decides which container an op is addressed to,
    /// and that one decides which ops may take the unscoped answer.
    ///
    /// It mirrors that method rather than calling it because `addressed` is
    /// private to `ProjectDocument` — but the two must not drift, and the
    /// reason is not tidiness: `AgentServer.performGroupedEdit` TRIES the ops
    /// on the handle first, purely, to turn a refusal into a message instead
    pub fn overwrite_clip(&self, track: u32, media: u32, at: Ticks) -> Result<Outcome, String> {
        self.require_track(track)?;
        let found = self.require_media(media)?.clone();
        let at = self.snapped(at).max(0);
        let length = self.whole_media_length(&found)?;
        // Both bounds are already on the frame grid, so the span is too.
        let end = at.saturating_add(length);

        let mut next = self.clone();
        for bound in [at, end] {
            let cut: Vec<u32> = next
                .clips_on_track(track)
                .iter()
                .filter(|c| c.start < bound && bound < clip_end(c))
                .map(|c| c.id)
                .collect();
            match next.split_clips(&cut, bound)? {
                Outcome::Applied(project) => next = project,
                Outcome::Identity => {}
                Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
            }
        }
        let inside: Vec<u32> = next
            .clips_on_track(track)
            .iter()
            .filter(|c| c.start >= at && clip_end(c) <= end)
            .map(|c| c.id)
            .collect();
        next.clips.retain(|c| !inside.contains(&c.id));

        let placed = match next.add_clip(track, media, at)? {
            Outcome::Applied(placed) => placed,
            Outcome::Identity => return Ok(Outcome::Identity),
            Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
        };
        self.finish(placed)
    }
}

    fn slip_amount(&self, clip: &Clip, delta: Ticks) -> Result<Option<Ticks>, String> {
        let (media, current) = match clip.source {
            Source::Media { media, r#in, .. } => (media, r#in),
            Source::Still { media, at } => (media, at),
            _ => return Err(format!("clip {} is not a media clip", clip.id)),
        };
        // Timeline ticks to source ticks, at this clip's rate. A sub-tick
        // move at a very slow speed rounds to nothing, which is a refusal
        // and not an edit.
        let moved_by = timeline_to_source(delta, clip.speed);
        if moved_by == 0 {
            return Ok(None);
        }

        // The last legal position of what the clip shows: a window is
        // pushed against the tail of the file, a still stops one frame
        // short of it. Both are `source_window.rs`'s, which is also where
        // the reasons for the two shapes are written down.
        let media = self.require_media(media)?;
        let last = match clip.source {
            Source::Still { .. } => self.last_still_time(media),
            _ => self.last_in_point(clip, media),
        };
        let slipped = current.saturating_add(moved_by).clamp(0, last);
        Ok(Some(slipped.saturating_sub(current)))
    }

